import {readFile,writeFile,mkdir} from 'node:fs/promises';
const core=await readFile(new URL('./worker.js',import.meta.url),'utf8');
if((core.match(/export default \{/g)||[]).length!==1)throw new Error('Unexpected gateway export');
const adapter=await readFile(new URL('./cloudbase-adapter.cjs',import.meta.url),'utf8');
const directory=new URL('../cloudbase-gateway/',import.meta.url);
await mkdir(directory,{recursive:true});
await writeFile(new URL('index.js',directory),
  '// Generated by console/gateway/build-cloudbase.mjs. Edit shared gateway sources.\n'+
  core.replace('export default {','const gateway = {')+'\n'+adapter);
await writeFile(new URL('package.json',directory),
  '{"name":"liquidvivo-cloudbase-gateway","private":true,"type":"commonjs","main":"index.js"}\n');
